<?php declare(strict_types=1);require_once __DIR__.'/../../bootstrap/app.php';use App\Services\Auth;use App\Services\MatchingService;use App\Services\OfferService;use App\Security\Csrf;use App\Support\Url;Auth::requirePermission('OFFER_CREATE');$loadId=(int)($_GET['load_id']??0);$load=MatchingService::findLoad($loadId);if(!$load){http_response_code(404);exit('Approved load not found.');}$candidates=array_values(array_filter(MatchingService::candidates($loadId),fn($r)=>$r['suitability_status']!=='unsuitable'));$errors=[];if($_SERVER['REQUEST_METHOD']==='POST'){if(!Csrf::verify($_POST['_csrf']??null))$errors[]='Invalid form token.';else try{$selected=$_POST['selected']??[];$items=[];foreach($selected as$matchId){$id=(int)$matchId;$items[]=['match_id'=>$id,'amount'=>$_POST['amount'][$id]??0,'currency'=>$_POST['currency'][$id]??'TZS','breakdown'=>['total_cost'=>$_POST['total_cost'][$id]??'','company_charges'=>$_POST['company_charges'][$id]??'','insurance'=>$_POST['insurance'][$id]??'','taxes'=>$_POST['taxes'][$id]??'']];}$n=OfferService::createForMatches($loadId,$items,(int)Auth::user()['id']);header('Location: '.Url::to('operations/offers.php?sent='.$n));exit;}catch(RuntimeException$e){$errors[]=$e->getMessage();}}$fx=OfferService::fxRate();$pageTitle='Send Offers';require BASE_PATH.'/app/Views/layout/header.php';?>
<div class="page-head"><div><span class="eyebrow dark">Commercial offer desk</span><h1>Send transport offers</h1><p><?=h($load['load_ref'].' · '.$load['origin_city'].' → '.$load['destination_city'])?></p></div><span class="badge">24-hour validity</span></div><?php foreach($errors as$e):?><div class="error"><?=h($e)?></div><?php endforeach;?>
<div class="notice">Select the required candidates and enter the final price in either TZS or USD. The equivalent currency appears automatically; the exchange calculation is not shown as a separate formula.</div>
<form method="post" data-fx-rate="<?=h($fx)?>"><input type="hidden" name="_csrf" value="<?=h(Csrf::token())?>"><?php foreach($candidates as$c):$id=(int)$c['match_id'];?><article class="card offer-card"><label class="choice-line"><input type="checkbox" name="selected[]" value="<?=h($id)?>"> <span><strong><?=h($c['registration_number'].' · '.($c['carrier_company_name']?:$c['carrier_user_name']))?></strong><small><?=h('Driver '.$c['driver_name'].' · '.$c['capacity_value'].' '.$c['capacity_unit'].' · '.$c['suitability_status'])?></small></span></label><div class="pricing-entry"><div class="field"><label>Offer currency</label><select name="currency[<?=h($id)?>]" class="offer-currency"><option value="TZS">TZS</option><option value="USD">USD</option></select></div><div class="field"><label>Final offer amount</label><input class="money-input offer-amount" inputmode="decimal" name="amount[<?=h($id)?>]" placeholder="0"><span class="field-help offer-equivalent">Enter an amount to see the equivalent.</span></div></div><h3>Price explanation</h3><div class="form-grid price-breakdown"><div class="field"><label>Transport cost</label><input class="money-input" inputmode="decimal" name="total_cost[<?=h($id)?>]" placeholder="0"></div><div class="field"><label>Company charges</label><input class="money-input" inputmode="decimal" name="company_charges[<?=h($id)?>]" placeholder="0"></div><div class="field"><label>Insurance</label><input class="money-input" inputmode="decimal" name="insurance[<?=h($id)?>]" placeholder="0"></div><div class="field"><label>Taxes</label><input class="money-input" inputmode="decimal" name="taxes[<?=h($id)?>]" placeholder="0"></div></div></article><?php endforeach;if(!$candidates):?><div class="card empty-state"><p>No offerable current candidates.</p></div><?php endif;?><button class="button" style="margin-top:18px" <?=!$candidates?'disabled':''?>>Send selected offers</button></form><?php require BASE_PATH.'/app/Views/layout/footer.php';
